const puppeteer = require('puppeteer');
const path = require('path');
const URL_ = 'file://' + path.resolve('/app/index.html');
const OUT = '<TMP>/ramen-check/shots/';
const sizes = [
  { name: 'desktop', w: 1440, h: 900, dpr: 1 },
  { name: 'phone-portrait', w: 390, h: 844, dpr: 2, mobile: true },
  { name: 'phone-landscape', w: 844, h: 390, dpr: 2, mobile: true },
  { name: 'ultrawide', w: 2560, h: 1080, dpr: 1 },
];
(async () => {
  const browser = await puppeteer.launch({ headless: true, args: ['--no-sandbox', '--enable-unsafe-swiftshader'] });
  const report = {};
  for (const s of sizes) {
    const page = await browser.newPage();
    const errors = [];
    const requests = [];
    page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
    page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.type() + ': ' + m.text()); });
    page.on('request', (r) => requests.push(r.url()));
    await page.setViewport({ width: s.w, height: s.h, deviceScaleFactor: s.dpr, isMobile: !!s.mobile, hasTouch: !!s.mobile });
    await page.goto(URL_, { waitUntil: 'load' });
    await new Promise((r) => setTimeout(r, 2500));
    await page.screenshot({ path: OUT + s.name + '.png' });
    const info = await page.evaluate(() => ({
      text: document.body.innerText.trim(),
      canvas: [document.getElementById('scene').width, document.getElementById('scene').height],
      scroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
      inner: [innerWidth, innerHeight],
    }));
    // frame rate over 3 seconds (headless, software GL: indicative only)
    const fps = await page.evaluate(() => new Promise((resolve) => {
      let n = 0; const t0 = performance.now();
      const tick = () => { n++; if (performance.now() - t0 < 3000) requestAnimationFrame(tick); else resolve(n / ((performance.now() - t0) / 1000)); };
      requestAnimationFrame(tick);
    }));
    report[s.name] = { ...info, fps: fps.toFixed(1), errors, externalRequests: requests.filter((u) => !u.startsWith('file:') && !u.startsWith('data:') && !u.startsWith('blob:')) };
    await page.close();
  }
  console.log(JSON.stringify(report, null, 2));
  await browser.close();
})().catch((e) => { console.error('FAILED', e); process.exit(1); });
EOF
