// ---- Backdrop: a cached dark base, a breathing ambient glow, out-of-focus lights.
function buildBase() {
  const { W, H, dpr, S, ox, oy } = view;
  const cx = (ox + BOWL_X * S) * dpr, cy = (oy + BROTH_Y * S) * dpr, big = Math.max(W, H) * dpr;
  base = document.createElement('canvas');
  base.width = Math.round(W * dpr);
  base.height = Math.round(H * dpr);
  const g = base.getContext('2d');
  g.fillStyle = gradient(g.createRadialGradient(cx, cy, 0, cx, cy, big * 0.8), [[0, '#1d100a'], [0.4, '#0d0604'], [1, '#040302']]);
  g.fillRect(0, 0, base.width, base.height);
}

