cd <TMP>/ramen-check && cat > interact.js <<'EOF'
const puppeteer = require('puppeteer');
const crypto = require('crypto');
const path = require('path');
const URL_ = 'file://' + path.resolve('/app/index.html');
const OUT = '<TMP>/ramen-check/shots/';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
(async () => {
  const browser = await puppeteer.launch({ headless: true, args: ['--no-sandbox', '--enable-unsafe-swiftshader'] });
  const hash = (page) => page.evaluate(() => document.getElementById('scene').toDataURL('image/png')).then((u) => crypto.createHash('md5').update(u).digest('hex').slice(0, 10));

  // 1) Interactive session on desktop.
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  await page.setViewport({ width: 1440, height: 900, deviceScaleFactor: 1 });
  await page.goto(URL_, { waitUntil: 'load' });
  await sleep(7000);
  console.log('animated hash A:', await hash(page));
  await sleep(700);
  console.log('animated hash B (should differ):', await hash(page));

  // Sweep the pointer across the broth.
  for (let i = 0; i <= 45; i++) {
    const x = 560 + (i / 45) * 320, y = 540 + Math.sin(i / 7) * 25;
    await page.mouse.move(x, y);
    await sleep(22);
    if (i === 30) await page.screenshot({ path: OUT + 'interact-sweep.png' });
  }
  await sleep(200);
  await page.screenshot({ path: OUT + 'interact-after-sweep.png' });

  // Click on the broth and capture the burst.
  await page.mouse.move(700, 600);
  await sleep(200);
  await page.mouse.down();
  await page.mouse.up();
  await sleep(350);
  await page.screenshot({ path: OUT + 'interact-click.png' });

  // Move far to the top-left corner to check parallax and cursor light.
  for (let i = 0; i <= 30; i++) { await page.mouse.move(700 - i * 20, 600 - i * 15); await sleep(16); }
  await sleep(1200);
  await page.screenshot({ path: OUT + 'interact-corner.png' });
  console.log('errors (interactive):', JSON.stringify(errors));
  await page.close();

  // 2) Reduced motion: a still frame that never changes.
  const rm = await browser.newPage();
  const rmErrors = [];
  rm.on('pageerror', (e) => rmErrors.push(e.message));
  await rm.emulateMediaFeatures([{ name: 'prefers-reduced-motion', value: 'reduce' }]);
  await rm.setViewport({ width: 1440, height: 900, deviceScaleFactor: 1 });
  await rm.goto(URL_, { waitUntil: 'load' });
  await sleep(1500);
  const r1 = await hash(rm);
  await sleep(2000);
  const r2 = await hash(rm);
  await rm.mouse.move(300, 300);
  await sleep(100);
  await rm.mouse.move(900, 700);
  await sleep(600);
  const r3 = await hash(rm);
  console.log('reduced-motion hashes:', r1, r2, r3, r1 === r2 && r2 === r3 ? '=> static (OK)' : '=> CHANGED (check)');
  await rm.screenshot({ path: OUT + 'reduced-motion.png' });
  console.log('errors (reduced):', JSON.stringify(rmErrors));

  // 3) Live switch: turn reduced-motion on at runtime; the loop should stop.
  await rm.emulateMediaFeatures([{ name: 'prefers-reduced-motion', value: 'no-preference' }]);
  await sleep(1200);
  const live1 = await hash(rm);
  await sleep(900);
  const live2 = await hash(rm);
  console.log('after switching back to motion, frames change:', live1 !== live2);
  await rm.close();
  await browser.close();
})().catch((e) => { console.error('FAILED', e); process.exit(1); });
EOF
